<?php $pageTitle='Reports';$active='reports';require_once __DIR__.'/../includes/auth.php';require_role('admin');$stats=[
'course_count'=>(int)$pdo->query("SELECT COUNT(*) FROM courses WHERE status='published'")->fetchColumn(),
'student_count'=>(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='student'")->fetchColumn(),
'enrollment_count'=>(int)$pdo->query('SELECT COUNT(*) FROM enrollments')->fetchColumn(),
'quiz_attempts'=>(int)$pdo->query('SELECT COUNT(*) FROM quiz_attempts')->fetchColumn(),
];
if(($_GET['export']??'')==='csv'){header('Content-Type: text/csv');header('Content-Disposition: attachment; filename="lms-course-report.csv"');$out=fopen('php://output','w');fputcsv($out,['Course','Teacher','Enrollments','Status']);$q=$pdo->query("SELECT c.title,u.full_name,COUNT(e.id),c.status FROM courses c JOIN users u ON u.id=c.teacher_id LEFT JOIN enrollments e ON e.course_id=c.id GROUP BY c.id ORDER BY COUNT(e.id) DESC");foreach($q as $r)fputcsv($out,[$r['title'],$r['full_name'],$r['COUNT(e.id)'],$r['status']]);fclose($out);exit;}
$top=$pdo->query("SELECT c.title,u.full_name teacher,COUNT(e.id) learners FROM courses c JOIN users u ON u.id=c.teacher_id LEFT JOIN enrollments e ON e.course_id=c.id GROUP BY c.id ORDER BY learners DESC")->fetchAll();$avg=(float)$pdo->query('SELECT COALESCE(AVG(percentage),0) FROM quiz_attempts')->fetchColumn();$completion=(float)$pdo->query('SELECT COALESCE(AVG(progress_percent),0) FROM enrollments')->fetchColumn();require_once __DIR__.'/../includes/ui.php';require_once __DIR__.'/../includes/app_start.php';?>
<div class="page-header"><div><div class="section-kicker mb-2">Analytics</div><h1>Reports</h1><p>High-level academic and platform statistics from MySQL.</p></div><a class="btn btn-primary" href="reports.php?export=csv">Export CSV</a></div><div class="row g-3 mb-4"><div class="col-6 col-xl-3"><?=statCard('collection','Published Courses',$stats['course_count'],'primary')?></div><div class="col-6 col-xl-3"><?=statCard('people','Students',$stats['student_count'],'success')?></div><div class="col-6 col-xl-3"><?=statCard('person-check','Enrollments',$stats['enrollment_count'],'warning')?></div><div class="col-6 col-xl-3"><?=statCard('ui-checks-grid','Quiz Attempts',$stats['quiz_attempts'],'primary')?></div></div><div class="row g-4"><div class="col-lg-7"><div class="card p-4"><h4>Course enrollment report</h4><div class="table-responsive mt-3"><table class="table"><thead><tr><th>Course</th><th>Teacher</th><th>Learners</th><th>Status</th></tr></thead><tbody><?php foreach($top as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['teacher'])?></td><td><?=e($r['learners'])?></td><td><?=badgeSoft('Published','success')?></td></tr><?php endforeach;?></tbody></table></div></div></div><div class="col-lg-5"><div class="card p-4"><h4>Platform indicators</h4><div class="d-flex justify-content-between py-3 border-bottom"><span class="text-muted">Average quiz score</span><strong><?=e(round($avg))?>%</strong></div><div class="d-flex justify-content-between py-3"><span class="text-muted">Average course progress</span><strong><?=e(round($completion))?>%</strong></div></div></div></div>
